:root {
  /* Colors */
  --color-cream-canvas: #ffffeb;
  --color-sand-surface: #e4e4d0;
  --color-forest-stage: #034f46;
  --color-ink: #1a1a1a;
  --color-ink-caption: #1a1a1ab3;
  --color-ink-whisper: #1a1a1a80;
  --color-stone-border: #d1d1c1;
  --color-linen-ring: #eeebe3;
  --color-lavender-signal: #f0d7ff;
  --color-ember-coral: #ff6c4c;
  --color-sunbeam-orange: #ffa946;
  --color-mint-pulse: #34d399;

  /* Typography — Font Families */
  --font-eb-garamond: "EB Garamond", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-figtree: "Figtree", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.3;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.3;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.3;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.3;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.3;
  --tracking-body-lg: 0px;
  --text-subheading: 32px;
  --leading-subheading: 0.95;
  --tracking-subheading: -0.96px;
  --text-heading-sm: 48px;
  --leading-heading-sm: 0.95;
  --tracking-heading-sm: -1.44px;
  --text-heading: 64px;
  --leading-heading: 0.95;
  --tracking-heading: -1.92px;
  --text-heading-lg: 75px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -2.25px;
  --text-display: 96px;
  --leading-display: 0.95;
  --tracking-display: -2.88px;
  --tracking-eyebrow: 1.12px;
  --leading-button: 1;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-56: 56px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-128: 128px;
  --spacing-160: 160px;

  /* Layout */
  --layout-max-width: 1240px;
  --layout-nav-width: 912px;
  --layout-prose-width: 768px;
  --layout-lede-width: 480px;
  --layout-section-gap: 128px;
  --layout-section-gap-mobile: 64px;
  --layout-card-padding: 16px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-xl: 32px;
  --radius-2xl: 48px;
  --radius-3xl: 80px;
  --radius-full: 1600px;

  /* Named Radii */
  --radius-cards: 48px;
  --radius-inner-tiles: 32px;
  --radius-small-cards: 16px;
  --radius-buttons: 8px;
  --radius-nav: 8px;
  --radius-pills: 1600px;
  --radius-badges: 52px;
  --radius-small-elements: 4px;
  --radius-avatars: 50%;
  --radius-sections: 80px 80px 0px 0px;

  /* Shadows */
  --shadow-subtle: 1px 1px 3px 0px rgba(0, 0, 0, 0.1);

  /* Surfaces */
  --surface-cream-canvas: #ffffeb;
  --surface-sand-surface: #e4e4d0;
  --surface-forest-stage: #034f46;
  --surface-ink: #1a1a1a;
}

